6: 
7: static int mandel(float c_re, float c_im, int count) {
8:     float z_re = c_re, z_im = c_im;
9:     int i;
10:     for (i = 0; i < count; ++i) {
11:         if (z_re * z_re + z_im * z_im > 4.f)
12:             break;
13: 
14:         float new_re = z_re * z_re - z_im * z_im;
15:         float new_im = 2.f * z_re * z_im;
16:         z_re = c_re + new_re;
17:         z_im = c_im + new_im;
18:     }
19: 
20:     return i;
21: }
22: 
23: void mandelbrot_serial(float x0, float y0, float x1, float y1, int width, int height, int maxIterations, int output[], int threads) {
24:     float dx = (x1 - x0) / width;
25:     float dy = (y1 - y0) / height;
26:     int worker_count = threads > 1 ? threads : 1;
27: 
28:     #pragma omp parallel for schedule(dynamic, 1) num_threads(worker_count) if (threads > 1)
29:     for (int j = 0; j < height; j++) {
30:         for (int i = 0; i < width; ++i) {
31:             float x = x0 + i * dx;
32:             float y = y0 + j * dy;
33: 
34:             int index = (j * width + i);
35:             output[index] = mandel(x, y, maxIterations);
36:         }
37:     }
38: }
39: #include <cstdint>
40: #include <cstring>
41: #include <cmath>
42: #include <algorithm>
43: #include <omp.h>
44: extern "C" void run(const void* input1,const void* input2,void* output,int n,int parameter,int threads)
45: {const float*a=(const float*)input1;mandelbrot_serial(a[0],a[1],a[2],a[3],n*3/2,n,parameter,(int*)output,threads);}

