23: static void mandel_four(const float c_re[4], const float c_im[4], int count, int result[4]) {
24:     float z_re[4], z_im[4];
25:     int active[4];
26:     const int limit = count > 0 ? count : 0;
27: 
28:     #pragma omp simd
29:     for (int lane = 0; lane < 4; ++lane) {
30:         z_re[lane] = c_re[lane];
31:         z_im[lane] = c_im[lane];
32:         active[lane] = 1;
33:         result[lane] = limit;
34:     }
35: 
36:     int active_lanes = 4;
37:     for (int iter = 0; iter < limit && active_lanes != 0; ++iter) {
38:         int escaped_lanes = 0;
39:         #pragma omp simd reduction(+:escaped_lanes)
40:         for (int lane = 0; lane < 4; ++lane) {
41:             if (active[lane]) {
42:                 if (z_re[lane] * z_re[lane] + z_im[lane] * z_im[lane] > 4.f) {
43:                     result[lane] = iter;
44:                     active[lane] = 0;
45:                     escaped_lanes += 1;
46:                 } else {
47:                     float new_re = z_re[lane] * z_re[lane] - z_im[lane] * z_im[lane];
48:                     float new_im = 2.f * z_re[lane] * z_im[lane];
49:                     z_re[lane] = c_re[lane] + new_re;
50:                     z_im[lane] = c_im[lane] + new_im;
51:                 }
52:             }
53:         }
54:         active_lanes -= escaped_lanes;
55:     }
56: }
