58: void mandelbrot_serial(float x0, float y0, float x1, float y1, int width, int height, int maxIterations, int output[]) {
59:     float dx = (x1 - x0) / width;
60:     float dy = (y1 - y0) / height;
61: 
62:     for (int j = 0; j < height; j++) {
63:         float y = y0 + j * dy;
64:         int i = 0;
65:         if (width >= 4) {
66:             for (; i <= width - 4; i += 4) {
67:                 float c_re[4], c_im[4];
68:                 int result[4];
69: 
70:                 #pragma omp simd
71:                 for (int lane = 0; lane < 4; ++lane) {
72:                     int pixel = i + lane;
73:                     c_re[lane] = x0 + pixel * dx;
74:                     c_im[lane] = y;
75:                 }
76: 
77:                 mandel_four(c_re, c_im, maxIterations, result);
78: 
79:                 #pragma omp simd
80:                 for (int lane = 0; lane < 4; ++lane) {
81:                     int index = j * width + i + lane;
82:                     output[index] = result[lane];
83:                 }
84:             }
85:         }
86:         for (; i < width; ++i) {
87:             float x = x0 + i * dx;
88:             int index = (j * width + i);
89:             output[index] = mandel(x, y, maxIterations);
90:         }
91:     }
92: }
