23: void mandelbrot_serial(float x0, float y0, float x1, float y1, int width, int height, int maxIterations, int output[]) {
24:     float dx = (x1 - x0) / width;
25:     float dy = (y1 - y0) / height;
26: 
27:     for (int j = 0; j < height; j++) {
28:         float y = y0 + j * dy;
29:         int i = 0;
30: 
31:         for (; i + 1 < width; i += 2) {
32:             float c_re[2];
33:             float z_re[2];
34:             float z_im[2];
35:             int result[2];
36: 
37:             #pragma omp simd
38:             for (int lane = 0; lane < 2; ++lane) {
39:                 int pixel = i + lane;
40:                 c_re[lane] = x0 + pixel * dx;
41:                 z_re[lane] = c_re[lane];
42:                 z_im[lane] = y;
43:                 result[lane] = maxIterations > 0 ? maxIterations : 0;
44:             }
45: 
46:             int any_active = 1;
47:             for (int iteration = 0; iteration < maxIterations && any_active; ++iteration) {
48:                 #pragma omp simd
49:                 for (int lane = 0; lane < 2; ++lane) {
50:                     int active = result[lane] == maxIterations;
51:                     float magnitude_squared = z_re[lane] * z_re[lane] + z_im[lane] * z_im[lane];
52:                     int escaped = active && magnitude_squared > 4.f;
53:                     int update = active && !escaped;
54: 
55:                     float new_re = z_re[lane] * z_re[lane] - z_im[lane] * z_im[lane];
56:                     float new_im = 2.f * z_re[lane] * z_im[lane];
57: 
58:                     if (escaped)
59:                         result[lane] = iteration;
60:                     if (update) {
61:                         z_re[lane] = c_re[lane] + new_re;
62:                         z_im[lane] = y + new_im;
63:                     }
64:                 }
65:                 any_active = (result[0] == maxIterations) || (result[1] == maxIterations);
66:             }
67: 
68:             #pragma omp simd
69:             for (int lane = 0; lane < 2; ++lane) {
70:                 int index = j * width + i + lane;
71:                 output[index] = result[lane];
72:             }
73:         }
74: 
75:         for (; i < width; ++i) {
76:             float x = x0 + i * dx;
77:             int index = j * width + i;
78:             output[index] = mandel(x, y, maxIterations);
79:         }
80:     }
81: }
