23: void mandelbrot_serial(float x0, float y0, float x1, float y1, int width, int height, int maxIterations, int output[], int threads) {
24:     float dx = (x1 - x0) / width;
25:     float dy = (y1 - y0) / height;
26:     const int worker_count = threads > 1 ? threads : 1;
27: 
28:     #pragma omp parallel for schedule(dynamic, 2) num_threads(worker_count) if(threads > 1)
29:     for (int j = 0; j < height; j++) {
30:         float y = y0 + j * dy;
31:         int i = 0;
32: 
33:         for (; width - i >= 8; i += 8) {
34:             float c_re[8];
35:             float z_re[8];
36:             float z_im[8];
37:             int pixel[8];
38:             int result[8];
39:             int active_count = maxIterations > 0 ? 8 : 0;
40: 
41:             for (int lane = 0; lane < 8; ++lane) {
42:                 pixel[lane] = i + lane;
43:                 c_re[lane] = x0 + pixel[lane] * dx;
44:                 z_re[lane] = c_re[lane];
45:                 z_im[lane] = y;
46:                 result[lane] = maxIterations > 0 ? maxIterations : 0;
47:             }
48: 
49:             for (int iteration = 0; iteration < maxIterations && active_count > 0; ++iteration) {
50:                 #pragma omp simd
51:                 for (int lane = 0; lane < active_count; ++lane) {
52:                     if (z_re[lane] * z_re[lane] + z_im[lane] * z_im[lane] > 4.f) {
53:                         result[lane] = iteration;
54:                     } else {
55:                         float new_re = z_re[lane] * z_re[lane] - z_im[lane] * z_im[lane];
56:                         float new_im = 2.f * z_re[lane] * z_im[lane];
57:                         z_re[lane] = c_re[lane] + new_re;
58:                         z_im[lane] = y + new_im;
59:                     }
60:                 }
61: 
62:                 int compacted = 0;
63:                 for (int lane = 0; lane < active_count; ++lane) {
64:                     if (result[lane] == maxIterations) {
65:                         if (compacted != lane) {
66:                             c_re[compacted] = c_re[lane];
67:                             z_re[compacted] = z_re[lane];
68:                             z_im[compacted] = z_im[lane];
69:                             pixel[compacted] = pixel[lane];
70:                             result[compacted] = result[lane];
71:                         }
72:                         ++compacted;
73:                     } else {
74:                         int index = j * width + pixel[lane];
75:                         output[index] = result[lane];
76:                     }
77:                 }
78:                 active_count = compacted;
79:             }
80: 
81:             if (maxIterations > 0) {
82:                 for (int lane = 0; lane < active_count; ++lane) {
83:                     int index = j * width + pixel[lane];
84:                     output[index] = result[lane];
85:                 }
86:             } else {
87:                 for (int lane = 0; lane < 8; ++lane) {
88:                     int index = j * width + pixel[lane];
89:                     output[index] = result[lane];
90:                 }
91:             }
92:         }
93: 
94:         for (; i < width; ++i) {
95:             float x = x0 + i * dx;
96:             int index = j * width + i;
97:             output[index] = mandel(x, y, maxIterations);
98:         }
99:     }
100: }
